export const TRANSACTIONS_SELL_NEW: Prisma.TransactionCreateManyInput[] = SELL_SOURCE_NEW.map(
  (tx) => {
    const tt = Number(tx.tt);
    const ttc = Number(tx.ttc);
    const markup = ttc - tt;
    return {
      id: `${tx.transaction_id}`,
      tt,
      fee: Math.trunc(((99.5 * markup + 995) / (markup + 1990)) * 100) / 100,
      ttc,
      transaction_type: 'SELL',
      status: tx.sale_status as TransactionStatus,
      user_id: tx.user_id,
      created_at: new Date().toISOString(),
    };
  }
);

export const TRANSACTION_SELL_LINES_NEW: Prisma.TransactionLotCreateManyInput[] =
  SELL_SOURCE_NEW.map((line) => ({
    id: line.id,
    transaction_id: line.transaction_id,
    item_id: line.item_id,
    inventory_lot_id: line.inventory_lot_id,
    quantity: line.quantity,
    line_type: line.line_type as SessionLineType,
    line_status: line.line_status as SessionStatus,
    sale_status: line.sale_status as TransactionStatus,
    tt: line.tt,
    ttc: line.ttc,
    user_id: line.user_id,
  }));
